    # Convert the number string into a list of integers
    digits = [int(d) for d in num_str]

    # If there are no multiplication signs to insert, return the number itself (as an integer)
    if K == 0:
        return int(''.join(map(str, digits)))

    # Find the maximum product by considering all possible positions to insert the K multiplication signs
    max_prod = 0
    for _ in range(K):
        current_prod = 1
        for digit in digits:
            current_prod *= digit
            if current_prod == 0:
                break
        max_prod = max(max_prod, current_prod)
        digits = [0] + digits[1:]

