def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i, char in enumerate(isbn):
            if char == '-':
                continue
            value = int(char)
            if char == 'X' and i == 9:
                value = 10
            total += value * (10 - i)
        return total % 11

    # Split the ISBN into segments
    parts = isbn.split('-')
    if len(parts) != 4:
        return isbn

    # Extract the first 9 digits and the checksum
    isbn_prefix = '-'.join(parts[:3])
    checksum = parts[3]

    # Calculate the checksum
    calculated_checksum = calculate_checksum(isbn_prefix)

    # Check if the checksum is correct
    if calculated_checksum == 0:
        return "Right"
    elif calculated_checksum == 1:
        return f"{isbn_prefix}-0" if checksum == 'X' else f"{isbn_prefix}-X"
    else:
        return f"{isbn_prefix}-{11 - calculated_checksum}"
