def count_passing_ways(n: int, m: int) -> int:
    if n == 1:
        return 1  # Only one way if there's only one student

    # Initialize a 2D list to store the number of ways to pass the ball
    dp = [[0 for _ in range(m + 1)] for _ in range(n)]

    # Base case: There's one way to pass the ball zero times (doing nothing)
    for i in range(n):
        dp[i][0] = 1

    # Fill the dp array
    for j in range(1, m + 1):
        for i in range(1, n):
            dp[i][j] = dp[i - 1][j - 1] + dp[i + 1][j - 1]

    # Since the students are in a circle, we need to consider the wrap-around
    return dp[1][m] + dp[n - 1][m]
