from collections import deque

def generate_numbers(n, rules) -> int:
    # Convert the number to a string for easier manipulation
    target = str(n)
    # Initialize a queue for BFS and a set to keep track of visited numbers
    queue = deque([target])
    visited = set([target])

    # Define a helper function to apply transformation rules to a given number
    def apply_rules(num_str):
        next_numbers = set()
        for i, char in enumerate(num_str):
            digit = int(char)
            for x, y in rules:
                if digit == x:
                    next_numbers.add(num_str[:i] + str(y) + num_str[i+1:])
        return next_numbers

    # Perform BFS
    while queue:
        current = queue.popleft()
        for next_num_str in apply_rules(current):
            if next_num_str not in visited:
                visited.add(next_num_str)
                queue.append(next_num_str)

    # Return the count of unique numbers generated
    return len(visited)
