    for participant, participant_statements in statements.items():
        for statement in participant_statements:
            if participant in liar_count:
                # Liars say the opposite of what is true
                if statement.startswith("I am guilty.") and participant in must_be_true:
                    return False
                if statement.startswith("I am not guilty.") and participant in must_be_true:
