    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: There is one way to arrange 0 pots
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            for k in range(1, a[i - 1] + 1):
                if j >= k:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

